import zipfile
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}


def col_index(ref):
    letters = "".join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx


def read_sheet(z, sheet_xml):
    root = ET.fromstring(z.read(sheet_xml))
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss.findall("m:si", NS):
            shared.append("".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t")))
    rows = {}
    for row in root.find("m:sheetData", NS):
        r = int(row.get("r"))
        for c in row.findall("m:c", NS):
            ref = c.get("r")
            t = c.get("t")
            v_el = c.find("m:v", NS)
            is_el = c.find("m:is", NS)
            formula = c.find("m:f", NS)
            val = None
            if t == "inlineStr" and is_el is not None:
                val = "".join(tx.text or "" for tx in is_el.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            elif v_el is not None:
                raw = v_el.text
                if t == "s":
                    val = shared[int(raw)]
                elif t == "b":
                    val = raw == "1"
                elif t == "str":
                    val = raw
                else:
                    try:
                        val = float(raw) if "." in raw or "E" in raw.upper() else int(raw)
                    except (ValueError, TypeError):
                        val = raw
            rows[(r, col_index(ref))] = (val, formula.text if formula is not None else None)
    return rows


with zipfile.ZipFile("budget.xlsx") as z:
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    sheet_name = wb.find("m:sheets/m:sheet", NS).get("name")
    sheet_xml = "xl/worksheets/sheet1.xml"
    cells = read_sheet(z, sheet_xml)

print(f"Sheet: {sheet_name}")

print("\n--- Expense line items (rows 11-22) ---")
expense_rows = []
for r in range(11, 23):
    category = cells.get((r, 1), (None, None))[0]
    item = cells.get((r, 2), (None, None))[0]
    amount = cells.get((r, 3), (None, None))[0]
    expense_rows.append((r, category, item, amount))
    print(f"  {category:15s} | {item:15s} | {amount}")

total = sum(row[3] for row in expense_rows)
print(f"\nTOTAL EXPENSES (all categories): {total}")

print("\n--- Per-category subtotals ---")
from collections import OrderedDict
cats = OrderedDict()
for r, cat, item, amt in expense_rows:
    cats.setdefault(cat, 0)
    cats[cat] += amt
for cat, amt in cats.items():
    print(f"  {cat:15s} | {amt}")
print(f"  {'TOTAL':15s} | {sum(cats.values())}")

print("\n--- Workbook's own formulas ---")
for (r, c), (val, formula) in sorted(cells.items()):
    if formula:
        print(f"  Cell r{r}c{c} ({formula}): {val}")

